78  static int muscle_match_card(sc_card_t *card)
    79  {
    80          sc_apdu_t apdu;
    81          u8 response[64];
    82          int r;
    83
    84          /* Since we send an APDU, the card's logout function may be called...
    85           * however it's not always properly nulled out... */
    86          card->ops->logout = NULL;
    87
    88          if (msc_select_applet(card, muscleAppletId, sizeof muscleAppletId) == 1) {
    89                  /* Muscle applet is present, check the protocol version to be sure */
    90                  sc_format_apdu(card, &apdu, SC_APDU_CASE_2, 0x3C, 0x00, 0x00);
    91                  apdu.cla = 0xB0;
    92                  apdu.le = 64;
    93                  apdu.resplen = 64;
    94                  apdu.resp = response;
    95                  r = sc_transmit_apdu(card, &apdu);
    96                  if (r == SC_SUCCESS && response[0] == 0x01) {
    97                          card->type = SC_CARD_TYPE_MUSCLE_V1;
    98                  } else {
    99                          card->type = SC_CARD_TYPE_MUSCLE_GENERIC;
   100                  }
   101                  return 1;
   259  int msc_select_applet(sc_card_t *card, u8 *appletId, size_t appletIdLength)
   260  {
   261          sc_apdu_t apdu;
   262          int r;
   263
   264          sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0xA4, 4, 0);
   265          apdu.lc = appletIdLength;
   266          apdu.data = appletId;
   267          apdu.datalen = appletIdLength;
   268          apdu.resplen = 0;
   269          apdu.le = 0;
   270
   271          r = sc_transmit_apdu(card, &apdu);
   272          LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
   273          if(apdu.sw1 == 0x90 && apdu.sw2 == 0x00)
   274                  return 1;
   275
   276          SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE,  SC_ERROR_CARD_CMD_FAILED);
   277  }
